const headword = entry => {
  const first=String(entry).trim().split(',')[0].trim();
  if(first==='a/ab'||first==='e/ex')return first;
  if(first.startsWith('-ne'))return '-ne';
  if(first.startsWith('nonne'))return 'nonne';
  if(first.startsWith('num'))return 'num';
  if(first.startsWith('quis?'))return 'quis';
  if(first==='tres n tria')return 'tres';
  if(first==='mille pl milia')return 'mille';
  return first.replace(/\s+(?:pl\b|senatoris\b).*$/,'').replace(/[!?]+$/,'').trim();
};
export const LATIN_BOOKLET_RECORDS = Object.freeze(SOURCE.trim().split('\n').map((line,index)=>{
  const [chapter,latin,english]=line.split('|');
  return Object.freeze({index:index+1,chapter:chapter==='N'?'Numbers':Number(chapter),
    latin,english,headword:headword(latin)});
}));
export const latinBookletKey = s=>String(s||'').normalize('NFD')
  .replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
export const latinBookletMeanings = english => {
  const text=String(english||'').trim();
  const bracketOnly=text.match(/^\(([^()]*)\)$/)?.[1]||'';
  const cleaned=text.replace(/\([^)]*\)/g,'').replace(/\bpl\s+/g,'')
    .replace(/\.{2,}/g,'').replace(/[!?]/g,', ').replace(/\s+/g,' ').trim();
  const parts=cleaned.split(/[;,]/).map(x=>x.trim()).filter(Boolean);
  const synonyms=parts.flatMap(p=>{
    if(!p.includes('/'))return [p];
    // Textbook compounds such as "he/she says" or "beg/ask for".
    const chunks=p.split('/').map(x=>x.trim()).filter(Boolean);
    if(chunks.length!==2)return [p];
    const tail=chunks[1].includes(' ')?chunks[1].slice(chunks[1].indexOf(' ')):'';
    return [p,chunks[0]+tail,chunks[1]];
  });
  return [...new Set([text,cleaned,bracketOnly,...parts,...synonyms]
    .map(v=>v.trim()).filter(Boolean))];
};
export const LATIN_BOOKLET_GROUPS = Object.freeze([...LATIN_BOOKLET_RECORDS.reduce((map,row)=>{
  const key=latinBookletKey(row.headword);
  if(!map.has(key))map.set(key,{key,headword:row.headword,
    latin:row.latin,entries:[],chapters:[],english:[],accepted:[]});
  const group=map.get(key);
  group.entries.push(row.latin);
  if(!group.chapters.includes(row.chapter))group.chapters.push(row.chapter);
  if(!group.english.includes(row.english))group.english.push(row.english);
  for(const meaning of latinBookletMeanings(row.english))
    if(!group.accepted.includes(meaning))group.accepted.push(meaning);
  return map;
},new Map()).values()].map(row=>Object.freeze(row)));
